func (r *TicketRepository) updateColumns(ctx context.Context, update *TicketUpdate) (map[string]any, error) {
	columns := map[string]any{}
	if update.Subject != nil {
		columns["subject"] = *update.Subject
	}
	if update.Body != nil && update.BodySetNull {
		return nil, fmt.Errorf("body cannot be updated with both value and null assignment")
	}
	if update.BodySetNull {
		columns["body"] = nil
	} else if update.Body != nil {
		columns["body"] = *update.Body
	}
	if update.Category != nil && update.CategorySetNull {
		return nil, fmt.Errorf("category cannot be updated with both value and null assignment")
	}
	if update.CategorySetNull {
		columns["category"] = nil
	} else if update.Category != nil {
		columns["category"] = *update.Category
	}
	if update.Priority != nil && update.PrioritySetNull {
		return nil, fmt.Errorf("priority cannot be updated with both value and null assignment")
	}
	if update.PrioritySetNull {
		columns["priority"] = nil
	} else if update.Priority != nil {
		columns["priority"] = *update.Priority
	}
	return columns, nil
}

// operationOptions are the stamps an operation's write of the row sets, none
// on a table with no updatedAt or updatedBy.
func (r *TicketRepository) operationOptions(ctx context.Context) *rules.ExecuteOptions {
	return nil
}

// createThroughCore is CreateOne on the repository's transaction: input's row
// stamped, created by the behaviors' core, whose uses initialize the fields
// they own, with the columns the insert writes, and read back.
func (r *TicketRepository) createThroughCore(ctx context.Context, input *TicketCreate) (*types.Ticket, error) {
	row := input.row()
	columns, err := r.createColumns(row)
	if err != nil {
		return nil, err
	}
	opts := &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns}}
	key, err := rules.RunCreate(ctx, rulesHost(r.tx), "Ticket", r.coreOwn(row), behaviorCaller(ctx), opts)
	if err != nil {
		return nil, err
	}
	id, err := types.ParseIdentityUUID(key)
	if err != nil {
		return nil, fmt.Errorf("create Ticket: the core's key %q: %w", key, err)
	}
	return r.GetOne(ctx, id, nil)
}

// upsertInputs are inputs as an upsert inserts them (D103): each one's row
// with the fields its behaviors own as the core's create of it gives them,
// run to its change set and not applied, so the insert writes what CreateOne
// would have, and the update, which sets none of them, leaves them as the
// row holds them. A refusal of the core's is returned before anything is
// written.
func (r *TicketRepository) upsertInputs(ctx context.Context, inputs []*TicketCreate) ([]*types.Ticket, error) {
	host := rulesHost(r.tx)
	rows := make([]*types.Ticket, 0, len(inputs))
	for _, input := range inputs {
		row := input.row()
		owned, err := rules.PrepareCreate(ctx, host, "Ticket", r.coreOwn(row), behaviorCaller(ctx), &rules.CreateOptions{ID: r.createKey(row)})
		if err != nil {
			return nil, err
		}
		if value, ok := owned["Provenance"]["inReview"]; ok {
			if err := json.Unmarshal(value, &row.ProvenanceInReview); err != nil {
				return nil, fmt.Errorf("upsert Ticket: the core's Provenance.inReview %s: %w", value, err)
			}
		}
		if value, ok := owned["status"]["status"]; ok {
			if err := json.Unmarshal(value, &row.Status); err != nil {
				return nil, fmt.Errorf("upsert Ticket: the core's status.status %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["status"]["enteredAt"]); err != nil {
			return nil, fmt.Errorf("upsert Ticket: the core's status.enteredAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.StatusEnteredAt = &value
		}
		rows = append(rows, row)
	}
	return rows, nil
}

// Allowed fields for Ticket (for validation and ordering)
var TicketAllowedFields = map[string]bool{
	"id":                   true,
	"subject":              true,
	"body":                 true,
	"category":             true,
	"priority":             true,
	"provenance_in_review": true,
	"status":               true,
	"status_entered_at":    true,
	"_version":             true,
}

// Quoted field names for Ticket (for SQL generation)
var TicketQuotedFields = map[string]string{
	"id":                   `id`,
	"subject":              `subject`,
	"body":                 `body`,
	"category":             `category`,
	"priority":             `priority`,
	"provenance_in_review": `provenance_in_review`,
	"status":               `status`,
	"status_entered_at":    `status_entered_at`,
	"_version":             `_version`,
}

// ticketSortColumns are the columns of Ticket's sort fields, by
// field, as FindPage's ORDER BY and keyset write them: qualified by the table,
// and by page_key, the alias of the subquery that reads the key's row. They
// are the only text of a sort that reaches its SQL (D60, amended). nulls is
// a column that may be null, whose nulls a page orders last (D112).
var ticketSortColumns = map[TicketSortField]struct {
	sql, key string
	nulls    bool
}{
	TicketSortById:              {`ticket.id`, `page_key.id`, false},
	TicketSortBySubject:         {`ticket.subject`, `page_key.subject`, false},
	TicketSortByBody:            {`ticket.body`, `page_key.body`, true},
	TicketSortByPriority:        {`ticket.priority`, `page_key.priority`, true},
	TicketSortByStatus:          {`ticket.status`, `page_key.status`, false},
	TicketSortByStatusEnteredAt: {`ticket.status_entered_at`, `page_key.status_entered_at`, true},
}

// buildTicketOrderByClause builds an ORDER BY clause for Ticket.
// quotedTable is the table's name as the FROM clause spells it, quoted when
// it is a keyword (a table named order is "order").
func buildTicketOrderByClause(orderBy []TicketOrderBy, quotedTable string) string {
	if len(orderBy) == 0 {
		return ""
	}

	var clauses []string
	for _, order := range orderBy {
		fieldStr := string(order.Field)
		direction := "ASC"
		if order.Desc {
			direction = "DESC"
		}
		// Use pre-computed quoted field name
		quotedField, ok := TicketQuotedFields[fieldStr]
		if !ok {
			quotedField = fieldStr // Fallback to unquoted if not found
		}
		clauses = append(clauses, fmt.Sprintf("%s.%s %s", quotedTable, quotedField, direction))
	}

	if len(clauses) == 0 {
		return ""
	}

	return " ORDER BY " + strings.Join(clauses, ", ")
}

func ticketUUIDValue(value any) (types.IdentityUUID, bool) {
	switch v := value.(type) {
	case types.IdentityUUID:
		return v, true
	case *types.IdentityUUID:
		if v == nil {
			var zero types.IdentityUUID
			return zero, false
		}
		return *v, true
	default:
		var zero types.IdentityUUID
		return zero, false
	}
}

func ticketUUIDPtr(value types.IdentityUUID) *types.IdentityUUID {
	return &value
}

