// GetManyByIDs retrieves multiple Ticket records by their IDs in a single query
func (r *TicketRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Ticket, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Ticket{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "subject", "body", "category", "priority", "provenance_in_review", "status", "status_entered_at", "_version" FROM ticket WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Ticket, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Ticket{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempBody sql.NullString
		var tempCategory *types.Category
		var tempPriority sql.NullString
		var tempProvenanceInReview *bool
		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Subject,

			&tempBody,

			&tempCategory,

			&tempPriority,

			&tempProvenanceInReview,

			&entity.Status,

			&tempStatusEnteredAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempBody.Valid {
			entity.Body = tempBody.String
		}
		if tempCategory != nil {
			entity.Category = tempCategory
		}
		if tempPriority.Valid {
			entity.Priority = tempPriority.String
		}
		if tempProvenanceInReview != nil {
			entity.ProvenanceInReview = tempProvenanceInReview
		}
		if tempStatusEnteredAt != nil {
			entity.StatusEnteredAt = tempStatusEnteredAt
		}

		// Set relationship IDs from scanned FK values

		entityID, ok := ticketUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

