// FindMany retrieves multiple Ticket records matching the filter, and how
// many it matches in all, -1 when the options skip the count
func (r *TicketRepository) FindMany(ctx context.Context, filter *TicketFilter, opts *TicketFindOptions) ([]*types.Ticket, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}

	// Build selected fields in OrderedMembers order so FK columns match scan order.
	fieldStrings := ticketFieldStrings(opts.Fields)

	// Validate fields
	if err := validateFields(fieldStrings, TicketAllowedFields); err != nil {
		return nil, 0, err
	}

	// Build SELECT clause
	selectFields := buildSelectFieldsTyped(fieldStrings, "ticket")
	if selectFields == "" {
		return nil, 0, fmt.Errorf("no valid fields specified")
	}

	// Build WHERE clause
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)

	// Build ORDER BY clause
	orderByClause := buildTicketOrderByClause(opts.OrderBy, `ticket`)

	// Build LIMIT/OFFSET clause
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)

	// Build query
	query := fmt.Sprintf(`SELECT %s FROM ticket%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)

	// Get total count, unless the options skip it (D89)
	totalCount := -1
	if !opts.SkipCount {
		countQuery := fmt.Sprintf(`SELECT COUNT(*) FROM ticket%s`, whereClause)

		var countRow pgx.Row
		if r.tx != nil {
			countRow = r.tx.QueryRow(ctx, countQuery, args...)
		} else {
			countRow = r.db.pool.QueryRow(ctx, countQuery, args...)
		}
		if err := countRow.Scan(&totalCount); err != nil {
			return nil, 0, fmt.Errorf("failed to get count: %w", err)
		}
	}

	results, err := r.findRows(ctx, "FindMany", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, 0, err
	}
	return results, totalCount, nil
}

// findRelated reads the rows filter finds as FindMany reads them, with no
// count: the read that loads a relation's rows for the rows of another
// table's read (D90), which counts nothing, as the TypeScript
// repositories' include does.
func (r *TicketRepository) findRelated(ctx context.Context, filter *TicketFilter, opts *TicketFindOptions) ([]*types.Ticket, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in FindOptions for performance")
	}
	fieldStrings := ticketFieldStrings(opts.Fields)
	if err := validateFields(fieldStrings, TicketAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "ticket")
	if selectFields == "" {
		return nil, fmt.Errorf("no valid fields specified")
	}
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)
	orderByClause := buildTicketOrderByClause(opts.OrderBy, `ticket`)
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)
	query := fmt.Sprintf(`SELECT %s FROM ticket%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)
	return r.findRows(ctx, "FindMany", query, args, fieldStrings, opts.Fields)
}

// ticketFieldStrings are the columns fields selects, in OrderedMembers
// order so FK columns match scan order, and the primary key when fields
// hydrates a hasMany relation, which maps the children by it.
func ticketFieldStrings(fields TicketFields) []string {
	var fieldStrings []string
	if fields.Id {
		fieldStrings = append(fieldStrings, "id")
	}
	if fields.Subject {
		fieldStrings = append(fieldStrings, "subject")
	}
	if fields.Body {
		fieldStrings = append(fieldStrings, "body")
	}
	if fields.Category {
		fieldStrings = append(fieldStrings, "category")
	}
	if fields.Priority {
		fieldStrings = append(fieldStrings, "priority")
	}
	if fields.ProvenanceInReview {
		fieldStrings = append(fieldStrings, "provenance_in_review")
	}
	if fields.Status {
		fieldStrings = append(fieldStrings, "status")
	}
	if fields.StatusEnteredAt {
		fieldStrings = append(fieldStrings, "status_entered_at")
	}
	if fields.Version {
		fieldStrings = append(fieldStrings, "_version")
	}
	return fieldStrings
}

// findRows runs query, a select of the columns fieldStrings names, in turn,
// with args, scans its rows, and hydrates the relations fields selects, as
// FindMany and FindPage read them. method names the caller in an error.
func (r *TicketRepository) findRows(ctx context.Context, method, query string, args []interface{}, fieldStrings []string, fields TicketFields) ([]*types.Ticket, error) {
	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Ticket{}
	for rows.Next() {
		result := &types.Ticket{}

		// Create temporary variables for nullable fields that need pointer scanning (per-row)

		var tempBody sql.NullString
		var tempCategory *types.Category
		var tempPriority sql.NullString
		var tempProvenanceInReview *bool
		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these directly on the struct)

		// Track whether special fields were selected so we can post-process after Scan.

		var selectedBody bool
		var selectedCategory bool
		var selectedPriority bool
		var selectedProvenanceInReview bool
		var selectedStatusEnteredAt bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "subject":
				scanDest[i] = &result.Subject
			case "body":
				scanDest[i] = &tempBody
				selectedBody = true
			case "category":
				scanDest[i] = &tempCategory
				selectedCategory = true
			case "priority":
				scanDest[i] = &tempPriority
				selectedPriority = true
			case "provenance_in_review":
				scanDest[i] = &tempProvenanceInReview
				selectedProvenanceInReview = true
			case "status":
				scanDest[i] = &result.Status
			case "status_entered_at":
				scanDest[i] = &tempStatusEnteredAt
				selectedStatusEnteredAt = true
			case "_version":
				scanDest[i] = &result.Version
			default:
				return nil, fmt.Errorf("unexpected field %q for Ticket.%s", fieldName, method)
			}
		}

		if err := rows.Scan(scanDest...); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present
		var jsonFieldDecodeErr error

		if selectedBody && tempBody.Valid {
			result.Body = tempBody.String
		}
		if selectedCategory && tempCategory != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.Category = tempCategory
		}
		if selectedPriority && tempPriority.Valid {
			result.Priority = tempPriority.String
		}
		if selectedProvenanceInReview && tempProvenanceInReview != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.ProvenanceInReview = tempProvenanceInReview
		}
		if selectedStatusEnteredAt && tempStatusEnteredAt != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.StatusEnteredAt = tempStatusEnteredAt
		}
		if jsonFieldDecodeErr != nil {
			return nil, jsonFieldDecodeErr
		}

		// Set relationship IDs from scanned FK values (hydration happens after loop)

		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	// Batch hydrate relationships (outside the row loop for efficiency)

	return results, nil
}

// FindPage reads a page of the Ticket rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *TicketRepository) FindPage(ctx context.Context, filter *TicketFilter, opts *TicketPageOptions) (*TicketPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Ticket rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = TicketSortById
	}
	column, ok := ticketSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Ticket sorts by id, subject, body, priority, status and statusEnteredAt, not %q", string(field))
	}
	byKey := field == TicketSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := ticketFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, TicketAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "ticket")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		afterKey := fmt.Sprintf(`ticket.id %s %s`, comparison, placeholder)
		if byKey {
			conditions = append(conditions, afterKey)
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			after := fmt.Sprintf(`(%s, ticket.id) %s ((SELECT %s FROM ticket AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder)
			if column.nulls {
				// Nulls come last in either direction (D112): after a
				// null, the nulls past the key; after a value, every null
				// and the values past it.
				after = fmt.Sprintf(`CASE (SELECT %s IS NULL FROM ticket AS page_key WHERE page_key.id = %s) WHEN TRUE THEN %s IS NULL AND %s WHEN FALSE THEN (%s IS NULL OR %s) END`,
					column.key, placeholder, column.sql, afterKey, column.sql, after)
			}
			conditions = append(conditions, after)
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if column.nulls {
		orderByClause = fmt.Sprintf(" ORDER BY %s %s NULLS LAST", column.sql, direction)
	}
	if !byKey {
		orderByClause += fmt.Sprintf(`, ticket.id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM ticket%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &TicketPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = ticketPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *TicketRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM ticket WHERE ticket.id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Ticket row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Ticket row through the behaviors' core (D103), in a
// transaction: each behavior's create initializes the fields it owns, and the
// row is read back. A refusal of the core's is returned as the *rules.Refusal
// it is.
func (r *TicketRepository) CreateOne(ctx context.Context, input *TicketCreate) (*types.Ticket, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Ticket, error) {
		return (&TicketRepository{tx: tx, txDB: r.database()}).createThroughCore(ctx, input)
	})
}

// ticketUniqueKeys are the conflict targets of Ticket's unique keys, and
// the assignment of the update an upsert that sets nothing names, which its
// WHERE FALSE never runs (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert reads back when it leaves them as they
// were, empty for a key over an expression, and that key's read of the row
// that holds one input's value of it, empty for a key over columns; and the
// key's columns as a batch insert's cells name them (D89).
var ticketUniqueKeys = map[TicketUniqueKey]struct {
	conflict, keep, rows, held string
	columns                    []string
}{
	TicketUniqueById: {`(id)`, `id = ticket.id`, `SELECT "id", "subject", "body", "category", "priority", "provenance_in_review", "status", "status_entered_at", "_version" FROM ticket WHERE (id) IN (%s)`, ``, []string{`id`}},
}

// ticketKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func ticketKeyOf(on TicketUniqueKey, row *types.Ticket) (string, bool) {
	switch on {
	case TicketUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *TicketRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Ticket, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *TicketRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Ticket, error) {
	result := &types.Ticket{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempBody sql.NullString
	var tempCategory *types.Category
	var tempPriority sql.NullString
	var tempProvenanceInReview *bool
	var tempStatusEnteredAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&result.Subject,

		&tempBody,

		&tempCategory,

		&tempPriority,

		&tempProvenanceInReview,

		&result.Status,

		&tempStatusEnteredAt,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if tempBody.Valid {
		result.Body = tempBody.String
	}
	if tempCategory != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.Category = tempCategory
	}
	if tempPriority.Valid {
		result.Priority = tempPriority.String
	}
	if tempProvenanceInReview != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.ProvenanceInReview = tempProvenanceInReview
	}
	if tempStatusEnteredAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.StatusEnteredAt = tempStatusEnteredAt
	}

	// Set relationship IDs from scanned FK values

	return result, nil
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, when the update sets no field or
// only if changed, and the second statement of an encrypted field.
func (r *TicketRepository) upsertRow(ctx context.Context, input *types.Ticket, on TicketUniqueKey, update *TicketUpdate, onlyIfChanged bool) (*UpsertResult[*types.Ticket], error) {
	key := ticketUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := ticketUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: subject
	fields = append(fields, `subject`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Subject)
	// Optional field: body - only add if set
	{
		if !reflect.ValueOf(input.Body).IsZero() {
			fields = append(fields, `body`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.Body)
		}
	}
	// Optional field: category - only add if set
	{
		if input.Category != nil {
			fields = append(fields, `category`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.Category)
		}
	}
	// Optional field: priority - only add if set
	{
		if !reflect.ValueOf(input.Priority).IsZero() {
			fields = append(fields, `priority`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.Priority)
		}
	}
	// Optional field: provenanceInReview - only add if set
	{
		if input.ProvenanceInReview != nil {
			fields = append(fields, `provenance_in_review`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.ProvenanceInReview)
		}
	}
	// Required field: status
	fields = append(fields, `status`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Status)
	// Optional field: statusEnteredAt - only add if set
	{
		if input.StatusEnteredAt != nil {
			fields = append(fields, `status_entered_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.StatusEnteredAt))
		}
	}

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Subject != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`subject = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `ticket.subject`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Subject)
	}
	if update.Body != nil && update.BodySetNull {
		return nil, fmt.Errorf("body cannot be updated with both value and null assignment")
	}
	if update.BodySetNull {
		setClauses = append(setClauses, `body = NULL`)
		compareCurrent = append(compareCurrent, `ticket.body`)
		compareNext = append(compareNext, `NULL`)
	} else if update.Body != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`body = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `ticket.body`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Body)
	}
	if update.Category != nil && update.CategorySetNull {
		return nil, fmt.Errorf("category cannot be updated with both value and null assignment")
	}
	if update.CategorySetNull {
		setClauses = append(setClauses, `category = NULL`)
		compareCurrent = append(compareCurrent, `ticket.category`)
		compareNext = append(compareNext, `NULL`)
	} else if update.Category != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`category = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `ticket.category`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Category)
	}
	if update.Priority != nil && update.PrioritySetNull {
		return nil, fmt.Errorf("priority cannot be updated with both value and null assignment")
	}
	if update.PrioritySetNull {
		setClauses = append(setClauses, `priority = NULL`)
		compareCurrent = append(compareCurrent, `ticket.priority`)
		compareNext = append(compareNext, `NULL`)
	} else if update.Priority != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`priority = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `ticket.priority`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Priority)
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field compares none, so its WHERE is FALSE:
		// it leaves the row as it is, its version, stamps and history all,
		// and reads it back below.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO ticket (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "subject", "body", "category", "priority", "provenance_in_review", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || assigned == 0),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Ticket]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Ticket]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged && assigned > 0:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with, which the update sets no field of
		// or which already held the update's values, read back by its key:
		// a soft-deleted one is ErrNotFound.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Ticket row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.heldOfKey(ctx, on, keyValues, input)
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Ticket]{Row: found, Status: UpsertUnchanged}
	}
	return upserted, nil
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// when update names no field or only if changed, and the second statement
// of each encrypted field.
func (r *TicketRepository) upsertBatches(ctx context.Context, inputs []*types.Ticket, on TicketUniqueKey, update TicketFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Ticket], error) {
	key := ticketUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Subject {
		setClauses = append(setClauses, `subject = EXCLUDED.subject`)
		compareCurrent = append(compareCurrent, `ticket.subject`)
		compareNext = append(compareNext, `EXCLUDED.subject`)
	}
	if update.Body {
		setClauses = append(setClauses, `body = EXCLUDED.body`)
		compareCurrent = append(compareCurrent, `ticket.body`)
		compareNext = append(compareNext, `EXCLUDED.body`)
	}
	if update.Category {
		setClauses = append(setClauses, `category = EXCLUDED.category`)
		compareCurrent = append(compareCurrent, `ticket.category`)
		compareNext = append(compareNext, `EXCLUDED.category`)
	}
	if update.Priority {
		setClauses = append(setClauses, `priority = EXCLUDED.priority`)
		compareCurrent = append(compareCurrent, `ticket.priority`)
		compareNext = append(compareNext, `EXCLUDED.priority`)
	}

	results := make([]UpsertResult[*types.Ticket], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := ticketUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: subject
			{
				cell := batchInsertCell{column: `subject`, set: true}
				cell.value = input.Subject
				row = append(row, cell)
			}
			// Optional field: body
			{
				cell := batchInsertCell{column: `body`}
				if !reflect.ValueOf(input.Body).IsZero() {
					cell.value = input.Body
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: category
			{
				cell := batchInsertCell{column: `category`}
				if input.Category != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.Category
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: priority
			{
				cell := batchInsertCell{column: `priority`}
				if !reflect.ValueOf(input.Priority).IsZero() {
					cell.value = input.Priority
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: provenanceInReview
			{
				cell := batchInsertCell{column: `provenance_in_review`}
				if input.ProvenanceInReview != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.ProvenanceInReview
					cell.set = true
				}
				row = append(row, cell)
			}
			// Required field: status
			{
				cell := batchInsertCell{column: `status`, set: true}
				cell.value = input.Status
				row = append(row, cell)
			}
			// Optional field: statusEnteredAt
			{
				cell := batchInsertCell{column: `status_entered_at`}
				if input.StatusEnteredAt != nil {
					cell.value = time.Time(*input.StatusEnteredAt)
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field compares none, so its WHERE is
			// FALSE: it leaves each row as it is, its version, stamps and
			// history all, and reads it back below.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO ticket (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "subject", "body", "category", "priority", "provenance_in_review", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || len(setClauses) == 0),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = ticketKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Ticket], len(prepared))
		for n, row := range returned {
			text, ok := ticketKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Ticket wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Ticket]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, when update
		// names no field or only if changed, which it reads back by its key,
		// or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged && len(setClauses) > 0 {
				return nil, fmt.Errorf("the Ticket row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Ticket, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Ticket row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Ticket]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *TicketRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Ticket, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Ticket
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert left as they were, as one whose
// update sets no field or one only if changed does (D89). A key no live
// row holds is ErrNotFound.
func (r *TicketRepository) rowsOfKeys(ctx context.Context, on TicketUniqueKey, keys [][]any, inputs []*types.Ticket) ([]*types.Ticket, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(ticketUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Ticket{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := ticketKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Ticket, len(inputs))
	for i, input := range inputs {
		text, _ := ticketKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Ticket row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// heldOfKey reads the row that holds input's value of the unique key on,
// keyValues the values of the key's columns its insert binds, which an
// upsert left as it was: by rowsOfKeys, or, for a key over an expression,
// whose columns read no row, by the expression's value over keyValues
// (sqlutil.UniqueKey.Held, D105). A key no live row holds is ErrNotFound.
func (r *TicketRepository) heldOfKey(ctx context.Context, on TicketUniqueKey, keyValues []any, input *types.Ticket) (*types.Ticket, error) {
	query := ticketUniqueKeys[on].held
	if query == "" {
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Ticket{input})
		if err != nil {
			return nil, err
		}
		return found[0], nil
	}
	var read pgx.Row
	if r.tx != nil {
		read = r.tx.QueryRow(ctx, query, keyValues...)
	} else {
		read = r.db.pool.QueryRow(ctx, query, keyValues...)
	}
	row, err := r.scanReturned(read, nil)
	if err == pgx.ErrNoRows {
		return nil, fmt.Errorf("the Ticket row that holds the key %s is deleted: %w", string(on), ErrNotFound)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the row the upsert left: %w", err)
	}
	return row, nil
}

// CreateMany inserts multiple Ticket rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *TicketRepository) CreateMany(ctx context.Context, inputs []*TicketCreate) ([]*types.Ticket, error) {
	if len(inputs) == 0 {
		return []*types.Ticket{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Ticket, error) {
		repo := &TicketRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Ticket, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Ticket row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *TicketRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *TicketUpdate) (*types.Ticket, error) {
	if update == nil {
		update = &TicketUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Ticket, error) {
		repo := &TicketRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Ticket", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns}); err != nil {
			return nil, behaviorNotFound(err, "Ticket", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Ticket records matching the filter
func (r *TicketRepository) UpdateMany(ctx context.Context, filter *TicketFilter, update *TicketUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Subject != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`subject = $%d`, paramNum))
		values = append(values, *update.Subject)
	}
	if update.Body != nil && update.BodySetNull {
		return 0, fmt.Errorf("body cannot be updated with both value and null assignment")
	}
	if update.BodySetNull {
		setClauses = append(setClauses, `body = NULL`)
	} else if update.Body != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`body = $%d`, paramNum))
		values = append(values, *update.Body)
	}
	if update.Category != nil && update.CategorySetNull {
		return 0, fmt.Errorf("category cannot be updated with both value and null assignment")
	}
	if update.CategorySetNull {
		setClauses = append(setClauses, `category = NULL`)
	} else if update.Category != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`category = $%d`, paramNum))
		values = append(values, *update.Category)
	}
	if update.Priority != nil && update.PrioritySetNull {
		return 0, fmt.Errorf("priority cannot be updated with both value and null assignment")
	}
	if update.PrioritySetNull {
		setClauses = append(setClauses, `priority = NULL`)
	} else if update.Priority != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`priority = $%d`, paramNum))
		values = append(values, *update.Priority)
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE ticket SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Ticket row by ID through the
// behaviors' core (D103), in a transaction. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *TicketRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Ticket", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Ticket", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Ticket records matching the filter
func (r *TicketRepository) DeleteMany(ctx context.Context, filter *TicketFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM ticket%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
